def solve():
    input = sys.stdin.read
    data = input().split()

    index = 0
    T = int(data[index])
    index += 1

    results = []

    for _ in range(T):
        n = int(data[index])
        m = int(data[index + 1])
        index += 2

        s = data[index]
        t = data[index + 1]
        index += 2

        def is_good(a):
            return all(a[i] != a[i + 1] for i in range(len(a) - 1))

        def can_make_good(s, t):
            if len(s) % 2 == 0:
                if all(s[i] == s[i + 1] for i in range(len(s) - 1)):
                    return False
            if len(t) % 2 == 0:
                if all(t[i] == t[i + 1] for i in range(len(t) - 1)):
                    return False

            if len(s) >= len(t):
                return is_good(s)

            for i in range(m):
                if s[-1] != t[i]:
                    candidate = s + t[:i] + s[1:]
                    if is_good(candidate):
                        return True
                if i < m - 1 and s[-1] != t[i + 1]:
                    candidate = s + t[:i + 1] + s[1:]
                    if is_good(candidate):
                        return True
            return False

        result = "YES" if can_make_good(s, t) else "NO"
        results.append(result)

    for result in results:
        print(result)

if __name__ == "__main__":
    solve()
