import itertools

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def generate_primes(digits):
    for r in range(len(digits), 1, -1):
        for combo in itertools.permutations(digits, r):
            num = int(''.join(combo))
            if is_prime(num):
                yield num

def solve():
    t = int(input())
    results = []
    for _ in range(t):
        digits = input()
        primes = list(generate_primes(digits))
        if primes:
            results.append(str(primes[0]))
        else:
            results.append('-1')
    for result in results:
