import numpy as np

def solve():
    t = int(input())
    results = []
    for _ in range(t):
        n, k = map(int, input().split())
        a = list(map(int, input().split()))

        # Initialize DP table
        dp = np.full((n + 1, k + 1), float('inf'))
        prefix_sum = [0] * (n + 1)

        for i in range(n):
            prefix_sum[i + 1] = prefix_sum[i] + abs(a[i])
            dp[i + 1][1] = prefix_sum[i + 1]

        for j in range(2, k + 1):
            for i in range(j - 1, n):
                for l in range(i):
                    dp[i + 1][j] = min(dp[i + 1][j], dp[l][j - 1] + prefix_sum[i + 1] - prefix_sum[l])

        results.append(int(dp[n][k]))

    for result in results:
        print(result)

if __name__ == "__main__":
