import heapq

def solve():
    def find_min_number(s):
        digits = []
        heap = list(range(1, 10))
        heapq.heapify(heap)

        while s > 0:
            if s >= 9 * len(digits) + 1:
                digit = heapq.heappop(heap)
                digits.append(digit)
                s -= digit
            else:
                digit = s % (9 - len(digits)) + 1
                digits.append(digit)
                s -= digit

        return int(''.join(map(str, sorted(digits))))

    t = int(input())
    results = [find_min_number(int(input())) for _ in range(t)]
